import{_ as t,c as n,j as e,a as _,o as l}from"./chunks/framework.CqbvlPrP.js";const u=JSON.parse('{"title":"第一百三十四章 数清楚大地泥土的数量","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/134第一百三十四章 数清楚大地泥土的数量.md","filePath":"meditation/巴利文大藏经/134第一百三十四章 数清楚大地泥土的数量.md"}'),r={name:"meditation/巴利文大藏经/134第一百三十四章 数清楚大地泥土的数量.md"};function o(s,a,i,d,p,c){return l(),n("div",null,a[0]||(a[0]=[e("h1",{id:"第一百三十四章-数清楚大地泥土的数量",tabindex:"-1"},[_("第一百三十四章 数清楚大地泥土的数量 "),e("a",{class:"header-anchor",href:"#第一百三十四章-数清楚大地泥土的数量","aria-label":'Permalink to "第一百三十四章 数清楚大地泥土的数量"'},"​")],-1),e("p",null,"完全读懂巴利文大藏经",-1),e("p",null,"相应部15相应2经/地经(无始相应/因缘篇/如来记说)",-1),e("p",null,"有个时候，佛陀住在舍卫城的祇树林给孤独园，有一天，佛陀对出家弟子们说：“弟子们，生死轮回是永无止境的，是无穷无尽的，不明白世间的真相、规则，被无知障碍，被贪爱束缚捆绑的众生，他们的生死轮回是循环不止的，他们无法知道自己生死轮回的起点在什么地方。",-1),e("p",null,"弟子们，就如同有个男子他把大地中所有的泥土做成了无数多个枣核大小的小泥丸，之后这个男子用数小泥丸的方法来估计自己祖先的数量，这个男子一边数小泥丸一边念到：「这是我的父亲，这是我父亲的父亲，这是我父亲父亲的父亲....」弟子们，就算这个男子把这些小泥丸全部都数完了，也无法数完他祖先的数量。这是什么原因呢？弟子们，因为生死轮回是循环不止的，是无穷无尽的！这些不明白世间的真相、规则，被无知障碍，被贪爱束缚捆绑的众生，他们的生死轮回也是循环不止的，也是无穷无尽的，他们也是无法知道他们自己生死轮回的起点在什么地方的。",-1),e("p",null,"弟子们，你们无数次的生死轮回，无数次的承受痛苦，无数次的经历不幸，无数次的忧愁、悲伤、苦闷、忧虑、绝望。无数次的死后埋入墓地。弟子们，你们要从世间解脱出来，要从生死轮回中解脱出来，就不要再挂念和执着世间一切的事物，就不要再执着和挂念自己一切的行为、言语、念想。这样你们就不会被世间一切的事物束缚捆绑，这样你们就不会被自己的行为、言语、念想束缚捆绑。这样你们就能最终从生死轮回中永远的解脱出来。”",-1),e("p",null,"佛陀说法后，听法的出家弟子们都再次的顶礼佛陀，随喜赞叹佛陀说法的无量功德，他们都按着佛陀所说的法去修行。",-1)]))}const f=t(r,[["render",o]]);export{u as __pageData,f as default};
